INSERT INTO gallery_items (store_id, title, description, image_url, material, print_method, tags, is_visible, sort_order) VALUES 
(1, '산업용 로봇 팔 프로토타입', 'FDM 방식으로 출력한 로봇 팔 어셈블리. 정밀한 조인트 테스트용.', '/placeholder-3d.jpg', 'ABS', 'FDM', '["시제품", "기구설계", "로봇"]', 1, 100),
(1, '치과 보철용 모델', '고해상도 SLA 프린트로 제작된 치아 모형. 뛰어난 표면 품질 제공.', '/placeholder-3d.jpg', 'Dental Resin', 'SLA', '["의료", "고정밀", "SLA"]', 1, 90),
(1, '커스텀 피규어 헤드', 'DLP 방식으로 출력된 1/6 스케일 피규어 헤드. 디테일한 머리카락 표현.', '/placeholder-3d.jpg', 'Standard Resin', 'DLP', '["피규어", "취미", "아트"]', 1, 80),
(1, '맞춤형 드론 프레임', '가볍고 튼튼한 카본 필라멘트로 출력한 FPV 드론용 프레임 개선판.', '/placeholder-3d.jpg', 'Carbon Fiber PLA', 'FDM', '["드론", "초경량", "고강도"]', 1, 70),
(1, '주얼리 캐스팅 마스터', '왁스 레진을 사용해 주조용 원본 모델로 출력. 탁월한 세밀도 구현.', '/placeholder-3d.jpg', 'Wax Resin', 'SLA', '["주얼리", "금속주조", "마스터"]', 1, 60),
(1, '건축 모형 풀세트', '아파트 단지 조감도 모형. 대형 파츠를 FDM으로 분할 출력하여 조립 후 도색.', '/placeholder-3d.jpg', 'PLA', 'FDM', '["건축", "대형출력", "조감도"]', 1, 50),
(1, '투명 렌즈 커버', 'Clear 레진으로 출력하여 광학 렌즈의 외부 보호용 커버 및 가이드 제작.', '/placeholder-3d.jpg', 'Clear Resin', 'SLA', '["광학장비", "투명", "SLA"]', 1, 40),
(1, '신발 미드솔 컨셉', '플렉시블(TPU) 소재를 사용해 유연하면서도 적당한 탄성을 지닌 신발 깔창.', '/placeholder-3d.jpg', 'TPU', 'FDM', '["웨어러블", "유연성", "TPU"]', 1, 30),
(1, '자동차 휠 컨셉 디자인', '미니어처 휠 모델을 정밀한 디테일로 출력, 추후 금형 테스트용.', '/placeholder-3d.jpg', 'Tough Resin', 'DLP', '["자동차", "디자인검증", "엔지니어링"]', 1, 20),
(1, '공학용 브라켓 어셈블리', '내열성 강화를 위해 나일론으로 출력. 강성과 내구성이 높음.', '/placeholder-3d.jpg', 'Nylon', 'FDM', '["브라켓", "내열성", "나일론"]', 1, 10),
(1, '의료용 해부학 해골', '의대생 교육용으로 정밀하게 재현된 두개골 모델.', '/placeholder-3d.jpg', 'PLA', 'FDM', '["교육용", "시청각자료"]', 1, 5),
(1, '빈티지 라디오 케이스', '소형 라디오 조립을 위해 디자인된 레트로 스타일 케이스 세트.', '/placeholder-3d.jpg', 'PETG', 'FDM', '["전자제품", "케이스", "레트로"]', 1, 1),
(1, '키보드 키캡 풀세트', '고객 맞춤형 인체공학적 디자인의 키캡 104키 세트.', '/placeholder-3d.jpg', 'Standard Resin', 'SLA', '["키보드", "커스텀", "PC부품"]', 1, 0),
(1, '기계식 시계 무브먼트', '기어 및 톱니바퀴의 맞물림 테스트용 초소형 파츠 출력.', '/placeholder-3d.jpg', 'High-Temp Resin', 'DLP', '["시계", "마이크로", "정밀기어"]', 1, -10),
(1, '스타트업 IoT 제품 기구물', '최종 금형 제작 전 보드 삽입 여부를 확인하기 위한 프로토타입.', '/placeholder-3d.jpg', 'ABS', 'FDM', '["스타트업", "IoT", "개발"]', 1, -20);
